const audioDB=(()=>{let dbp;const open=()=>dbp||(dbp=new Promise((resolve,reject)=>{const r=indexedDB.open('nexa-music-offline',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('tracks'))r.result.createObjectStore('tracks',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}));const all=async()=>{const db=await open();return new Promise((resolve,reject)=>{const r=db.transaction('tracks').objectStore('tracks').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})};const put=async(v)=>{const db=await open();return new Promise((resolve,reject)=>{const r=db.transaction('tracks','readwrite').objectStore('tracks').put(v);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})};const del=async(id)=>{const db=await open();return new Promise((resolve,reject)=>{const r=db.transaction('tracks','readwrite').objectStore('tracks').delete(id);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})};return{all,put,del}})();
