function greeting(){const h=new Date().getHours(),minute=new Date().getMinutes(),total=h*60+minute;const word=total>=300&&total<720?'Buongiorno':total>=720&&total<1080?'Buon pomeriggio':'Buonasera';const name=state.name?esc(state.name):'';const w=state.lang==='en'?(total>=300&&total<720?'Good morning':total>=720&&total<1080?'Good afternoon':'Good evening'):word;return name?`${w},<br><span class="greetingName">${name}</span>!`:`${w}!`}
