function bind(){document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===b));render()});const filePicker=$('#files');if(filePicker){filePicker.onchange=async e=>{await importFiles(e.target.files);e.target.value=''}}const homeFiles=$('#homeFiles');if(homeFiles)homeFiles.onchange=async e=>{try{await importFiles(e.target.files)}catch(err){console.error('Home audio import failed',err);alert(state.lang==='it'?'Impossibile importare il file audio.':'Unable to import audio.')}finally{e.target.value=''}};/* LRC/Karaoke rimosso */document.querySelectorAll('[data-more]').forEach(b=>b.onclick=e=>{e.stopPropagation();const s=state.songs.find(x=>x.id===b.dataset.more);if(s)showSongMenu(s,b)});/* karaoke removed */$('#play').onclick=toggle;$('#fullPlay').onclick=toggle;$('#next').onclick=()=>next(1);$('#fullNext').onclick=()=>next(1);$('#prev').onclick=()=>next(-1);$('#fullPrev').onclick=()=>next(-1);$('#seek').oninput=e=>seek(e.target.value);$('#fullSeek').oninput=e=>seek(e.target.value);$('#now').onclick=()=>$('#fullOverlay').classList.add('open');$('#closeFull').onclick=()=>$('#fullOverlay').classList.remove('open');$('#shuffleBtn')?.addEventListener('click',()=>{state.shuffle=!state.shuffle;updateModeButtons()});$('#repeatBtn')?.addEventListener('click',()=>{if(!state.repeat&&!state.repeatOne){state.repeat=true}else if(state.repeat){state.repeat=false;state.repeatOne=true}else{state.repeatOne=false}updateModeButtons()});const timer=$('#sleepTimer');if(timer)timer.onchange=()=>setSleepTimer(Number(timer.value));state.audio.ontimeupdate=updateProgress;state.audio.onplay=()=>{state.youtubePlaying=false;setPlayerText()};state.audio.onpause=()=>setPlayerText();state.audio.onended=()=>{if(state.repeatOne){state.audio.currentTime=0;state.audio.play().catch(()=>{});return}if(state.songs.length>0){next(1);return}state.audio.pause();state.audio.currentTime=0;setPlayerText();updateProgress()};state.audio.onloadedmetadata=updateProgress;updateModeButtons();updateGlobalTimer()}
function updateGreeting(){const g=$('#greeting');if(g)g.innerHTML=greeting()}
async function initAuth(){try{const s=await window.hatchable?.auth?.getSession();const u=s?.user;if(!u){if(!navigator.onLine){await restoreOfflineTracks();updateGreeting();return}location.replace('./login.html');return}state.authEmail=u.email||'';if(!state.name)state.name=u.name||u.display_name||u.email?.split('@')[0]||'';if(!state.profileImage&&u.image)state.profileImage=u.image;let profile=null;try{const r=await fetch('/api/profile',{cache:'no-store'});if(r.ok)profile=await r.json()}catch(e){console.warn('Profile lookup failed',e)}if(profile){state.firstName=profile.first_name||'';state.lastName=profile.last_name||'';state.displayName=profile.display_name||'';state.birthDate=profile.birth_date||'';if(profile.language==='it'||profile.language==='en')state.lang=profile.language;if(profile.profile_image_url)state.profileImage=profile.profile_image_url;state.name=state.displayName||state.name;state.birthday=!!state.birthDate&&new Date().toISOString().slice(5,10)===state.birthDate.slice(5,10);const avatar=$('#profile');if(avatar){avatar.innerHTML=state.profileImage?`<img src="${esc(state.profileImage)}" alt="Profilo">`:(state.name?esc(state.name[0].toUpperCase()):'N')}}if(!profile?.display_name){showRegistrationForm(u)}else{save();updateGreeting();if(state.birthday)showBirthday()}const p=$('#profile');if(p)p.title=state.lang==='it'?'Profilo / esci':'Profile / sign out';if(p)p.onclick=async()=>{if(confirm(state.lang==='it'?'Vuoi uscire da NEXA Music?':'Sign out of NEXA Music?')){try{await window.hatchable.auth.signOut()}finally{location.replace('./login.html')}}}}catch(e){console.warn('Auth unavailable',e);if(!navigator.onLine){await restoreOfflineTracks();updateGreeting();return}location.replace('./login.html')}}
function showRegistrationForm(u){if(document.querySelector('#nexaRegistration'))return;const overlay=document.createElement('div');overlay.id='nexaRegistration';overlay.style.cssText='position:fixed;inset:0;z-index:9999;display:grid;place-items:center;padding:20px;background:rgba(0,12,20,.82);backdrop-filter:blur(10px)';overlay.innerHTML=`<div style="width:min(460px,100%);padding:26px;border-radius:24px;background:var(--panel,#101b24);box-shadow:0 20px 70px rgba(0,0,0,.45)"><div class="pill">NEXA MUSIC</div><h2 style="margin:12px 0 6px">${state.lang==='it'?'Completa la registrazione':'Complete registration'}</h2><p class="muted" style="margin-bottom:18px">${state.lang==='it'?'Il tuo account è stato creato. Inserisci i dati del tuo profilo.':'Your account was created. Complete your profile.'}</p><label style="display:block;margin:10px 0 6px">Email</label><input id="regEmail" value="${esc(u.email||'')}" disabled style="width:100%;box-sizing:border-box"><label style="display:block;margin:10px 0 6px">Nome visualizzato</label><input id="regDisplay" placeholder="Edoardo" style="width:100%;box-sizing:border-box"><label style="display:block;margin:10px 0 6px">Nome</label><input id="regFirst" style="width:100%;box-sizing:border-box"><label style="display:block;margin:10px 0 6px">Cognome</label><input id="regLast" style="width:100%;box-sizing:border-box"><button id="regSave" class="primary" style="width:100%;margin-top:18px">${state.lang==='it'?'Completa registrazione':'Complete registration'}</button><p id="regError" class="muted" style="margin:10px 0 0"></p></div>`;document.body.appendChild(overlay);$('#regSave').onclick=async()=>{const display=$('#regDisplay').value.trim(),first=$('#regFirst').value.trim(),last=$('#regLast').value.trim(),err=$('#regError');if(!display||!first||!last){err.textContent=state.lang==='it'?'Compila nome visualizzato, nome e cognome.':'Fill display name, first name and last name.';return}const b=$('#regSave');b.disabled=true;try{const r=await fetch('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:display,first_name:first,last_name:last,birth_date:''})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Profile error');state.displayName=display;state.name=display;state.firstName=first;state.lastName=last;save();overlay.remove();updateGreeting();render()}catch(e){err.textContent=e.message;b.disabled=false}}}
function showBirthday(){const el=document.createElement('div');el.className='birthdayBanner';el.innerHTML=`🎂 ${state.lang==='it'?`Buon compleanno, ${esc(state.displayName||state.name)}! 🎉`:`Happy birthday, ${esc(state.displayName||state.name)}! 🎉`}`;document.body.appendChild(el)}
window.nexaImportFiles=async function(files){const list=Array.from(files||[]);if(!list.length)return;let added=0;for(const f of list){const isAudio=f.type?.startsWith('audio/')||/\.(mp3|wav|wave|m4a|m4b|m4p|aac|adts|flac|ogg|oga|opus|webm|weba|aiff|aif|aifc|alac|wma|amr|awb|3gp|3g2|ac3|ec3|dts|mka|mp2|mpa|m2a|m1a|au|snd|caf|ape|tta|wv|voc|mid|midi)$/i.test(f.name||'');if(!isAudio)continue;const id=(globalThis.crypto?.randomUUID?.()||('local-'+Date.now()+'-'+Math.random().toString(36).slice(2)));const url=URL.createObjectURL(f);const meta={id,title:(f.name||'Audio').replace(/\.[^.]+$/,''),artist:'Artista sconosciuto',album:'Album sconosciuto',source:'local',audioFormat:((f.name||'').match(/\.([^.]+)$/)||['','audio'])[1].toUpperCase(),blob:f};state.songs.push({...meta,url,file:f});added++;try{await audioDB.put(meta)}catch(e){console.warn('Offline save failed',e)}}if(added){localStorage.nexaOfflineReady='1';state.tab='mp3';render();if(!state.current)play(state.songs[state.songs.length-1])}else alert(state.lang==='it'?'Nessun file audio selezionato.':'No audio file selected.')}
async function searchOnline(q){q=(q||'').trim();if(!q)return;state.searchSeq=(state.searchSeq||0)+1;const seq=state.searchSeq;state.tab='search';const c=$('#content');c.innerHTML=`<div class="aihead"><span class="pill">ONLINE MUSIC</span><h2>${state.lang==='it'?'Cerca musica':'Search music'}</h2><p class="muted">${state.lang==='it'?'Catalogo gratuito con musica pubblicata per lo streaming.':'Free catalog with music published for streaming.'}</p></div><div class="empty">${state.lang==='it'?'Ricerca in corso…':'Searching…'}</div>`;try{const [a,b,y]=await Promise.allSettled([fetch('/api/music/search?q='+encodeURIComponent(q)),fetch('/api/music/archive?q='+encodeURIComponent(q)),fetch('/api/youtube/search?q='+encodeURIComponent(q))]);const read=async x=>x.status==='fulfilled'&&x.value.ok?x.value.json():{data:[]};const [ad,bd,yd]=await Promise.all([read(a),read(b),read(y)]);if(seq!==state.searchSeq)return;const ytData=yd.data||[];const freeData=[...(ad.data||[]),...(bd.data||[])];state.onlineResults=[...freeData,...ytData].map(s=>({...s,id:s.id||'online-'+crypto.randomUUID(),url:s.streamUrl,youtube:!!s.youtube,videoId:s.videoId||''}));showOnlineResults()}catch(e){c.innerHTML=`<div class="empty">${esc(state.lang==='it'?'Non è stato possibile cercare musica online.':'Online music search is unavailable.')}</div>`}}
function setupSpeechButton(btn,input,submit){if(!btn||!input)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){btn.title='Dettatura non supportata da questo browser';return}let rec=null,timer=null,finishing=false,finalParts=[];const normalizeSpeech=t=>String(t||'').replace(/\s+/g,' ').trim();const buildText=()=>normalizeSpeech(finalParts.filter(Boolean).join(' '));const finish=()=>{clearTimeout(timer);timer=null;finishing=true;if(rec){try{rec.stop()}catch(e){} }btn.classList.remove('listening');const q=buildText();input.value=q;rec=null;if(q)submit()};const armSilence=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(buildText())finish()},3000)};btn.onclick=()=>{if(rec){finish();return}finalParts=[];finishing=false;input.value='';rec=new SR();rec.lang=state.lang==='it'?'it-IT':'en-US';rec.continuous=true;rec.interimResults=true;rec.maxAlternatives=1;btn.classList.add('listening');rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];const text=normalizeSpeech(r[0]?.transcript);if(!text)continue;if(r.isFinal){finalParts[i]=text}else{interim=normalizeSpeech(interim+' '+text)}}input.value=normalizeSpeech(buildText()+' '+interim);armSilence()};rec.onend=()=>{clearTimeout(timer);btn.classList.remove('listening');if(finishing){rec=null;return}if(rec){try{rec.start()}catch(e){rec=null}}};rec.onerror=e=>{clearTimeout(timer);btn.classList.remove('listening');if(e.error==='not-allowed'||e.error==='service-not-allowed'){rec=null;return}if(e.error==='no-speech'){if(buildText())finish();else rec=null}};try{rec.start()}catch(e){rec=null;btn.classList.remove('listening')}}}function addSearchBox(){const f=$('#musicSearch');if(!f)return;f.onsubmit=e=>{e.preventDefault();searchOnline($('#musicQuery').value.trim())};setupSpeechButton($('#musicMic'),$('#musicQuery'),()=>f.requestSubmit())}
function spotifyRedirectUri(){return location.origin+'/'}
function spotifySaveTokens(d){state.spotify.accessToken=d.access_token||'';state.spotify.refreshToken=d.refresh_token||state.spotify.refreshToken;state.spotify.expiresAt=Date.now()+Math.max(30,(d.expires_in||3600)-60)*1000;if(state.spotify.accessToken)sessionStorage.nexaSpotifyAccessToken=state.spotify.accessToken;if(state.spotify.refreshToken)localStorage.nexaSpotifyRefreshToken=state.spotify.refreshToken;sessionStorage.nexaSpotifyExpiresAt=String(state.spotify.expiresAt)}
function randomString(n=64){const a=new Uint8Array(n);crypto.getRandomValues(a);return [...a].map(x=>('0'+x.toString(16)).slice(-2)).join('')}
async function sha256Base64Url(v){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v));return btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function spotifyConnect(){const id=state.spotify.clientId.trim();if(!id)return alert(state.lang==='it'?'Inserisci prima il Client ID della tua app Spotify Developer.':'Enter your Spotify Developer app Client ID first.');const verifier=randomString();const challenge=await sha256Base64Url(verifier);const st=randomString(24);sessionStorage.nexaSpotifyVerifier=verifier;sessionStorage.nexaSpotifyState=st;sessionStorage.nexaSpotifyClientId=id;const scopes='streaming user-read-email user-read-private user-modify-playback-state user-read-playback-state';const u=new URL('https://accounts.spotify.com/authorize');u.search=new URLSearchParams({client_id:id,response_type:'code',redirect_uri:spotifyRedirectUri(),code_challenge_method:'S256',code_challenge:challenge,state:st,scope:scopes}).toString();location.href=u.toString()}
async function spotifyCallback(){const p=new URLSearchParams(location.search);const code=p.get('code');const returnedState=p.get('state');if(!code)return false;const expected=sessionStorage.nexaSpotifyState;if(!expected||returnedState!==expected){alert(state.lang==='it'?'Autorizzazione Spotify non valida.':'Invalid Spotify authorization.');history.replaceState({},'',location.pathname);return true}const verifier=sessionStorage.nexaSpotifyVerifier;const clientId=sessionStorage.nexaSpotifyClientId||state.spotify.clientId;try{const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:clientId,grant_type:'authorization_code',code,redirect_uri:spotifyRedirectUri(),code_verifier:verifier})});const d=await r.json();if(!r.ok)throw new Error(d.error_description||d.error||'Spotify token error');state.spotify.clientId=clientId;spotifySaveTokens(d);localStorage.nexaSettings=JSON.stringify({...JSON.parse(localStorage.nexaSettings||'{}'),spotifyClientId:clientId});await spotifyInitPlayer();const me=await spotifyApi('/v1/me');state.spotify.user=me;alert(state.lang==='it'?`Spotify collegato a ${me.display_name||me.id}! 🎧`:`Spotify connected to ${me.display_name||me.id}! 🎧`)}catch(e){alert((state.lang==='it'?'Collegamento Spotify fallito: ':'Spotify connection failed: ')+e.message)}finally{sessionStorage.removeItem('nexaSpotifyVerifier');sessionStorage.removeItem('nexaSpotifyState');history.replaceState({},'',location.pathname)}return true}
async function spotifyRefresh(){if(!state.spotify.refreshToken||!state.spotify.clientId)return false;try{const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'refresh_token',refresh_token:state.spotify.refreshToken,client_id:state.spotify.clientId})});const d=await r.json();if(!r.ok)throw new Error(d.error_description||'Refresh failed');spotifySaveTokens(d);return true}catch(e){spotifyDisconnect(false);return false}}
async function spotifyToken(){if(state.spotify.accessToken&&Date.now()<state.spotify.expiresAt)return state.spotify.accessToken;return await spotifyRefresh()?state.spotify.accessToken:null}
async function spotifyApi(path,opts={}){const token=await spotifyToken();if(!token)throw new Error('Spotify non collegato');let r=await fetch('https://api.spotify.com'+path,{...opts,headers:{...(opts.headers||{}),Authorization:'Bearer '+token,'Content-Type':'application/json'}});if(r.status===401&&await spotifyRefresh())r=await fetch('https://api.spotify.com'+path,{...opts,headers:{...(opts.headers||{}),Authorization:'Bearer '+state.spotify.accessToken,'Content-Type':'application/json'}});if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.error?.message||`Spotify HTTP ${r.status}`)}return r.status===204?null:r.json()}
async function spotifyInitPlayer(){if(!state.spotify.accessToken||state.spotify.player)return;if(!window.Spotify){await new Promise(resolve=>{const old=window.onSpotifyWebPlaybackSDKReady;window.onSpotifyWebPlaybackSDKReady=()=>{old?.();resolve()};setTimeout(resolve,5000)})}if(!window.Spotify)return;state.spotify.player=new Spotify.Player({name:'NEXA Music',getOAuthToken:async cb=>cb(await spotifyToken()),volume:0.8,enableMediaSession:true});state.spotify.player.addListener('ready',({device_id})=>{state.spotify.deviceId=device_id});state.spotify.player.addListener('authentication_error',({message})=>console.warn('Spotify auth',message));state.spotify.player.addListener('account_error',({message})=>alert(state.lang==='it'?'Serve Spotify Premium per il player web.':'Spotify Premium is required for the web player.'));state.spotify.player.addListener('playback_error',({message})=>console.warn('Spotify playback',message));await state.spotify.player.connect()}
async function spotifyPlayUri(uri){await spotifyInitPlayer();if(!state.spotify.deviceId)throw new Error('Spotify player non pronto');await spotifyApi('/v1/me/player',{method:'PUT',body:JSON.stringify({device_ids:[state.spotify.deviceId],play:true})});await spotifyApi('/v1/me/player/play?device_id='+encodeURIComponent(state.spotify.deviceId),{method:'PUT',body:JSON.stringify({uris:[uri]})})}
function spotifyDisconnect(show=true){state.spotify.player?.disconnect?.();state.spotify.player=null;state.spotify.deviceId='';state.spotify.accessToken='';state.spotify.refreshToken='';state.spotify.expiresAt=0;sessionStorage.removeItem('nexaSpotifyAccessToken');sessionStorage.removeItem('nexaSpotifyExpiresAt');localStorage.removeItem('nexaSpotifyRefreshToken');if(show){render();alert(state.lang==='it'?'Spotify scollegato.':'Spotify disconnected.')}}
async function initSpotify(){if(!navigator.onLine)return;if(await spotifyCallback())return;if(state.spotify.accessToken&&Date.now()>=state.spotify.expiresAt)await spotifyRefresh();if(state.spotify.accessToken)await spotifyInitPlayer()}
function parseLrc(t){const out=[];for(const line of String(t||'').split(/\r?\n/)){const text=line.replace(/\[(?:\d{2}:\d{2}(?:\.\d+)?|\d+:\d{2}(?:\.\d+)?)\]/g,'').trim();const tags=[...line.matchAll(/\[(\d{1,3}):(\d{2})(?:\.(\d{1,3}))?\]/g)];for(const m of tags){const ms=m[3]?Number((m[3]+'00').slice(0,3)):0;const time=Number(m[1])*60+Number(m[2])+ms/1000;if(text)out.push({time,text})}}return out.sort((a,b)=>a.time-b.time)}
async function loadLrc(f){if(!f)return;state.lrc=parseLrc(await f.text());state.lrcText=f.name;state.tab='karaoke';render()}
function ytCommand(func,args=[]){const f=state.youtubeFrame;if(!f?.contentWindow)return false;f.contentWindow.postMessage(JSON.stringify({event:'command',func,args}),'*');return true}function syncYoutubeProgress(){if(!state.current?.youtube||!state.youtubeReady)return;ytCommand('getCurrentTime');ytCommand('getDuration')}window.addEventListener('message',e=>{if(e.origin!=='https://www.youtube.com')return;let d;try{d=typeof e.data==='string'?JSON.parse(e.data):e.data}catch{return}if(d?.event==='onReady'){state.youtubeReady=true;ytCommand('addEventListener',['onStateChange']);ytCommand('addEventListener',['onPlaybackQualityChange']);ytCommand('getVideoDuration');ytCommand('playVideo');return}if(d?.event==='infoDelivery'&&d.info){if(typeof d.info.currentTime==='number')state.youtubeTime=d.info.currentTime;if(typeof d.info.duration==='number')state.youtubeDuration=d.info.duration;const pct=state.youtubeDuration?state.youtubeTime/state.youtubeDuration*100:0;['seek','fullSeek'].forEach(id=>{const el=$('#'+id);if(el)el.value=String(pct)});const cur=fmt(state.youtubeTime||0),rem='-'+fmt(Math.max(0,(state.youtubeDuration||0)-(state.youtubeTime||0)));['clock','fullClock'].forEach(id=>{const el=$('#'+id);if(el)el.textContent=cur});['remain','fullRemain'].forEach(id=>{const el=$('#'+id);if(el)el.textContent=rem});if(state.youtubePendingSeek!=null&&state.youtubeDuration){const n=state.youtubePendingSeek;state.youtubePendingSeek=null;ytCommand('seekTo',[state.youtubeDuration*n/100,true])}return}if(d?.event!=='onStateChange')return;const s=Number(d.info);if(s===1){state.youtubePlaying=true}else if(s===2||s===0||s===5){state.youtubePlaying=false}setPlayerText()});function ensureYoutubeDock(){const dock=$('#youtubeDock');if(!dock)return null;dock.style.display='block';dock.hidden=false;let close=dock.querySelector('.youtubeClose');if(!close){close=document.createElement('button');close.className='youtubeClose';close.type='button';close.setAttribute('aria-label','Chiudi video');close.textContent='×';close.onclick=e=>{e.stopPropagation();dock.style.display='none';dock.hidden=true;state.youtubeClosed=true};dock.appendChild(close)}return dock}function playYoutube(s){if(!s?.videoId)return;const previous=state.current;state.current=s;state.audio.pause();const dock=ensureYoutubeDock();if(dock){state.youtubeClosed=false;dock.style.display='block';dock.hidden=false}let frame=state.youtubeFrame;if(!frame){frame=document.createElement('iframe');frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.title='YouTube player';frame.className='youtubeEmbed';frame.dataset.videoId=String(s.videoId);frame.src='https://www.youtube.com/embed/'+encodeURIComponent(s.videoId)+'?autoplay=1&playsinline=1&rel=0&controls=1&enablejsapi=1&origin='+encodeURIComponent(location.origin);dock?.appendChild(frame);state.youtubeFrame=frame;state.youtubeReady=false;frame.addEventListener('load',()=>{const f=state.youtubeFrame;if(!f?.contentWindow)return;f.contentWindow.postMessage(JSON.stringify({event:'listening',id:'nexa-youtube',channel:'nexa'}),'*');ytCommand('addEventListener',['onStateChange']);ytCommand('addEventListener',['onReady']);ytCommand('playVideo')},{once:true})}else if(frame.dataset.videoId!==String(s.videoId)){if(dock&&frame.parentElement!==dock)dock.appendChild(frame);frame.style.display='block';frame.dataset.videoId=String(s.videoId);state.youtubeReady=false;ytCommand('loadVideoById',[String(s.videoId)]);setTimeout(()=>ytCommand('playVideo'),350)}else{if(dock&&frame.parentElement!==dock)dock.appendChild(frame);frame.style.display='block';ytCommand('playVideo')}state.youtubePlaying=true;setPlayerText();fetchLyricsForCurrent();if(state.tab!=='search')state.tab='search';showOnlineResults();setPlayerText()}async function fetchLyricsForCurrent(){const s=state.current;if(!s?.title)return;try{const artist=(s.artist||'').trim()||'Unknown';const p=new URLSearchParams({title:s.title.trim(),artist});if(s.album)p.set('album',s.album);if(s.duration)p.set('duration',String(Math.round(s.duration)));const r=await fetch('/api/lyrics/search?'+p.toString(),{cache:'no-store'});if(!r.ok){state.lrc=[];state.lrcText='';state.current.lyrics='';state.current.syncedLyrics='';if(state.tab==='karaoke')render();return}const d=await r.json();if(!d.found){state.lrc=[];state.lrcText='';state.current.lyrics='';state.current.syncedLyrics='';if(state.tab==='karaoke')render();return}state.lrc=parseLrc(d.syncedLyrics||'');state.lrcText=d.title||s.title;state.current.lyrics=d.plainLyrics||'';state.current.syncedLyrics=d.syncedLyrics||'';if(state.tab==='karaoke')render()}catch(e){console.warn('Automatic lyrics lookup failed',e);if(state.tab==='karaoke')render()}}function showLyrics(){if(!state.current)return alert(state.lang==='it'?'Seleziona prima un brano.':'Select a song first.');state.tab='karaoke';render();if(!state.lrc.length&&!state.current.lyrics)fetchLyricsForCurrent()}function play(s){if(!s)return;if(s.youtube)return playYoutube(s);state.current=s;state.youtubePlaying=false;ytCommand('pauseVideo');const dock=$('#youtubeDock');if(dock)dock.style.display='none';state.audio.src=s.url;state.audio.play().catch(()=>{});setPlayerText();fetchLyricsForCurrent();render();if(state.tab==='search')showOnlineResults()}
function showOnlineResults(){const c=$('#content');const dock=$('#youtubeDock');const preservedYoutubeFrame=state.youtubeFrame;if(preservedYoutubeFrame&&dock&&!dock.contains(preservedYoutubeFrame))dock.appendChild(preservedYoutubeFrame);if(!state.onlineResults?.length){c.innerHTML=`<div class="empty">${state.lang==='it'?'Nessun risultato trovato.':'No results found.'}</div>`;return}const yt='';const youtubeResults=state.onlineResults.filter(s=>s.youtube);const otherResults=state.onlineResults.filter(s=>!s.youtube);const list=s=>s.map(x=>`<div class="song onlineSong ${state.current?.id===x.id?'playing':''}"><button class="songplay onlineplay" data-oid="${esc(x.id)}">${state.current?.id===x.id?'⏸':'▶'}</button>${x.artwork?`<img class="songArt" src="${esc(x.artwork)}" alt="">`:'<div class="songArt fallback">♫</div>'}<div><b>${esc(x.title)}</b><small>${esc(x.artist)} · ${esc(x.album||x.source||'Online')} · ${x.youtube?'YouTube':(x.fullPlayback?'Full track':'Preview')}</small></div><span class="sourceTag">${esc(x.source||'Online')}</span><button class="heart onlineHeart" data-fav-online="${esc(x.id)}" aria-label="Preferiti">${state.favorites.has(x.id)?'♥':'♡'}</button><button class="moreBtn onlineMore" data-more-online="${esc(x.id)}" aria-label="Azioni">&#8942;</button></div>`).join('');c.innerHTML=`<div class="onlineHead"><div><span class="pill">ONLINE MUSIC</span><h2>${state.lang==='it'?'Risultati musicali':'Music results'}</h2><p class="muted">${state.lang==='it'?'Ricerca su cataloghi gratuiti e YouTube.':'Search across free catalogs and YouTube.'}</p></div><span class="resultCount">${state.onlineResults.length}</span></div>${yt}${youtubeResults.length?`<div class="sourceSection"><h3>▶️ YouTube <span>${youtubeResults.length}</span></h3><div class="songs">${list(youtubeResults)}</div></div>`:''}${otherResults.length?`<div class="sourceSection"><h3>🎵 ${state.lang==='it'?'Altre sorgenti':'Other sources'} <span>${otherResults.length}</span></h3><div class="songs">${list(otherResults)}</div></div>`:''}`;if(state.current?.youtube&&state.current.videoId){const dock=$('#youtubeDock');if(dock&&state.youtubeFrame&&state.youtubeFrame.parentElement!==dock)dock.appendChild(state.youtubeFrame)}document.querySelectorAll('.onlineplay').forEach(b=>b.onclick=()=>{const s=state.onlineResults.find(x=>x.id===b.dataset.oid);if(s)play(s)});document.querySelectorAll('.onlineHeart').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.favOnline;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);save();showOnlineResults()});document.querySelectorAll('.onlineMore').forEach(b=>b.onclick=e=>{e.stopPropagation();const s=state.onlineResults.find(x=>x.id===b.dataset.moreOnline);if(s)showSongMenu(s,b)})}
function setPlayerText(){if(!state.current)return;['nowTitle','fullTitle'].forEach(id=>{if($('#'+id))$('#'+id).textContent=state.current.title});['nowArtist','fullArtist'].forEach(id=>{if($('#'+id))$('#'+id).textContent=state.current.artist});const playing=state.current.youtube?!!state.youtubePlaying:!state.audio.paused;$('#play').textContent=playing?'⏸':'▶';$('#fullPlay').textContent=playing?'⏸':'▶'}
async function toggle(){if(!state.current&&state.songs[0]){await play(state.songs[0]);return}if(!state.current)return;try{if(state.current.youtube){if(state.youtubePlaying){ytCommand('pauseVideo');state.youtubePlaying=false}else{ytCommand('playVideo');state.youtubePlaying=true}}else{if(state.audio.paused)await state.audio.play();else state.audio.pause()}}catch(e){console.warn('Playback error',e)}setPlayerText()}
function next(dir){if(!state.songs.length)return;let i=state.songs.indexOf(state.current);if(state.shuffle||dir===1)i=Math.floor(Math.random()*state.songs.length);else i=(i+dir+state.songs.length)%state.songs.length;play(state.songs[i])}
function seek(v){const n=Math.max(0,Math.min(100,Number(v)||0));if(state.current?.youtube){const duration=Number(state.youtubeDuration)||0;if(duration)ytCommand('seekTo',[duration*n/100,true]);else state.youtubePendingSeek=n;return}if(state.audio.duration)state.audio.currentTime=state.audio.duration*n/100}
function updateModeButtons(){const s=$('#shuffleBtn'),r=$('#repeatBtn');if(s){s.classList.toggle('activeMode',state.shuffle);s.title=state.shuffle?'Casuale attivo':'Casuale'}if(r){r.classList.toggle('activeMode',state.repeat||state.repeatOne);r.textContent=state.repeatOne?'🔂':'🔁';r.title=state.repeatOne?'Ripeti brano':'Ripeti playlist'}}
function setSleepTimer(mins){clearTimeout(state.sleepTimer);state.sleepTimer=null;state.sleepTimerEnd=mins?Date.now()+mins*60000:0;const timer=$('#sleepTimer');if(timer)timer.value=String(mins||0);if(mins)state.sleepTimer=setTimeout(()=>{state.audio.pause();state.sleepTimerEnd=0;setPlayerText();updateProgress();updateGlobalTimer()},mins*60000);updateGlobalTimer()}
function updateGlobalTimer(){const left=state.sleepTimerEnd?Math.max(0,state.sleepTimerEnd-Date.now()):0;const text=left?`${Math.floor(left/3600000)}:${String(Math.floor(left%3600000/60000)).padStart(2,'0')}:${String(Math.floor(left%60000/1000)).padStart(2,'0')}`:'';['globalTimerLeft','timerLeft'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=text});const g=$('#globalTimer');if(g)g.classList.toggle('hidden',!left)}
function showSongMenu(s,anchor){document.querySelector('.songMenu')?.remove();const m=document.createElement('div');m.className='songMenu';const rows=state.playlists.map((p,i)=>{const inPl=Array.isArray(p.ids)&&p.ids.includes(s.id);return `<button data-pl-toggle="${i}">${inPl?'− Rimuovi da':'＋ Aggiungi a'} ${esc(p.name)}</button>`}).join('');m.innerHTML=`${rows||'<button disabled>Nessuna playlist creata</button>'}${state.tab==='mp3'?`<button data-remove-mp3 style="color:#ff4d5f;font-weight:700">✕ Rimuovi da MP3</button>`:''}<button data-favpl>${state.favorites.has(s.id)?'♡ Rimuovi dai preferiti':'♥ Aggiungi ai preferiti'}</button>`;document.body.appendChild(m);const r=anchor.getBoundingClientRect();m.style.left=Math.max(8,Math.min(window.innerWidth-m.offsetWidth-8,r.left-120))+'px';m.style.top=(r.bottom+6)+'px';m.querySelectorAll('[data-pl-toggle]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const p=state.playlists[Number(b.dataset.plToggle)];if(!p)return;const ids=Array.isArray(p.ids)?p.ids:(p.ids=[]);p.tracks=Array.isArray(p.tracks)?p.tracks:[];const idx=ids.indexOf(s.id);if(idx>=0){ids.splice(idx,1);p.tracks=p.tracks.filter(x=>x.id!==s.id)}else{ids.push(s.id);p.tracks.push({id:s.id,title:s.title,artist:s.artist,artwork:s.artwork||'',youtube:!!s.youtube,videoId:s.videoId||''})}save();m.remove()});const removeMp3=m.querySelector('[data-remove-mp3]');if(removeMp3)removeMp3.onclick=async e=>{e.preventDefault();e.stopPropagation();if(!confirm(state.lang==='it'?`Rimuovere "${s.title}" dagli MP3?`:`Remove "${s.title}" from MP3?`))return;try{await audioDB.del(s.id)}catch(err){console.warn('Audio delete failed',err)}state.songs=state.songs.filter(x=>x.id!==s.id);state.playlists.forEach(p=>{p.ids=Array.isArray(p.ids)?p.ids.filter(id=>id!==s.id):[];if(Array.isArray(p.tracks))p.tracks=p.tracks.filter(x=>x.id!==s.id)});if(state.current?.id===s.id){state.audio.pause();state.audio.removeAttribute('src');state.audio.load();state.current=null}save();m.remove();render()};m.querySelector('[data-favpl]').onclick=()=>{state.favorites.has(s.id)?state.favorites.delete(s.id):state.favorites.add(s.id);save();m.remove();render()};setTimeout(()=>document.addEventListener('click',()=>m.remove(),{once:true}),0)}
const fmt=n=>{n=Math.max(0,Math.floor(n||0));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0')};
function updateProgress(){if(state.audio.duration){const p=state.audio.currentTime/state.audio.duration*100;$('#seek').value=p;$('#fullSeek').value=p;const cur=fmt(state.audio.currentTime),rem='-'+fmt(state.audio.duration-state.audio.currentTime);$('#clock').textContent=cur;$('#remain').textContent=rem;$('#fullClock').textContent=cur;$('#fullRemain').textContent=rem}const lines=document.querySelectorAll('.lyric');if(lines.length&&state.lrc.length){let active=-1;for(let i=0;i<state.lrc.length;i++){if(state.lrc[i].time<=state.audio.currentTime)active=i;else break}lines.forEach((x,i)=>x.classList.toggle('current',i===active));if(active>=0){const el=lines[active];const box=document.querySelector('.lyrics');if(box&&el)el.scrollIntoView({behavior:'smooth',block:'center'})}}}
function card(s){return `<div class="song"><button class="songplay" data-id="${s.id}">▶</button><div><b>${esc(s.title)}</b><small>${esc(s.artist)}</small></div><button class="heart" data-fav="${s.id}">${state.favorites.has(s.id)?'♥':'♡'}</button><button class="moreBtn" data-more="${s.id}" aria-label="Azioni">&#8942;</button></div>`}
function renderExpansions(c){c.innerHTML='<h2>Espansioni</h2><div class="settings"><div class="setting integrations"><div><b>Sorgenti musicali</b><label>Collega e apri le sorgenti musicali disponibili.</label></div><div class="integrationBtns"><a class="secondaryBtn" href="https://open.spotify.com/" target="_blank" rel="noopener">🟢 Spotify Premium</a><a class="secondaryBtn" href="https://music.youtube.com/" target="_blank" rel="noopener">▶️ YouTube Music</a><a class="secondaryBtn" href="https://freetouse.com/" target="_blank" rel="noopener">🎵 Free To Use</a><a class="secondaryBtn" id="lyraDirect" href="https://lyramusic.app/" target="_blank" rel="noopener noreferrer">🎧 Lyra Music</a></div></div><div class="setting"><div><b>Spotify Web Player</b><label>Il player Spotify richiede un account Premium e una configurazione Spotify Developer.</label></div><div class="spotifyControls"><input id="spotifyClientId" placeholder="Spotify Client ID" autocomplete="off"><button class="secondaryBtn" id="spotifySetup">Accedi con Spotify</button><button class="secondaryBtn" id="spotifyDisconnect">Scollega</button></div><small class="muted">Redirect URI da inserire in Spotify Developer: <code></code></small></div></div>';const cid=$('#spotifyClientId');if(cid)cid.value=state.spotify.clientId||'';const uri=c.querySelector('code');if(uri)uri.textContent=spotifyRedirectUri();const setup=$('#spotifySetup');if(setup)setup.textContent=state.spotify.accessToken?'Collegato ✓':'Accedi con Spotify';if(setup)setup.onclick=async()=>{state.spotify.clientId=$('#spotifyClientId')?.value.trim()||state.spotify.clientId;localStorage.nexaSettings=JSON.stringify({...JSON.parse(localStorage.nexaSettings||'{}'),spotifyClientId:state.spotify.clientId});if(state.spotify.accessToken){await spotifyInitPlayer();alert('Spotify è già collegato. 🎧')}else await spotifyConnect()};const disconnect=$('#spotifyDisconnect');if(disconnect)disconnect.onclick=()=>spotifyDisconnect();}
function render(){const c=$('#content');if(state.tab==='mp3'){c.innerHTML=`<div class="rowtitle"><h2>MP3</h2><span>${state.songs.length} ${state.lang==='it'?'file audio':'audio files'}</span></div><div class="songs">${state.songs.map(card).join('')||`<div class="empty">${state.lang==='it'?'Nessun file audio importato.':'No imported audio files.'}</div>`}</div>`;hookSongs()}else if(state.tab==='home')c.innerHTML=`<div class="hero"><div><span class="pill">NEXA MUSIC</span><h2>${state.lang==='it'?'La tua musica.':'Your music.'}<br><em>${state.lang==='it'?'Come vuoi tu.':'Your way.'}</em></h2><p>${state.lang==='it'?'Importa MP3, crea playlist e attiva il karaoke.':'Import MP3s, create playlists and use karaoke.'}</p><div style="display:flex;align-items:center;gap:14px;margin:20px 0"><label title="Importa MP3 e altri file audio" style="width:64px;height:64px;border-radius:50%;background:#1597ff;color:white;display:flex;align-items:center;justify-content:center;font-size:38px;font-weight:300;cursor:pointer;box-shadow:0 8px 24px rgba(21,151,255,.35);flex:0 0 64px"><span>+</span><input id="homeFiles" type="file" accept="audio/*" multiple onchange="window.nexaImportFiles(this.files)" style="display:none"></label><div><b style="display:block">${state.lang==='it'?'Importa audio':'Import audio'}</b><small style="display:block;color:var(--muted);margin-top:4px">${state.lang==='it'?'Premi + per importare MP3 e altri file audio dal dispositivo':'Press + to import MP3 and other audio files from your device'}</small></div></div></div><div class="bigdisc">♫</div></div><div class="rowtitle"><h2>${t('libraryTitle')}</h2><span>${state.songs.length} ${state.lang==='it'?'brani':'songs'}</span></div><div class="songs">${state.songs.slice(0,8).map(card).join('')||`<div class="empty">${t('empty')}</div>`}</div>`;else if(state.tab==='library')c.innerHTML=`<h2>${t('libraryTitle')}</h2><p class="muted">${state.songs.length}</p><div class="songs">${state.songs.map(card).join('')||`<div class="empty">${t('empty')}</div>`}</div>`;else if(state.tab==='favorites'){const all=[...state.songs,...state.onlineResults];const a=all.filter((s,i,arr)=>state.favorites.has(s.id)&&arr.findIndex(x=>x.id===s.id)===i);c.innerHTML=`<h2>${t('favorites')} ♥</h2><div class="songs">${a.map(s=>s.youtube?`<div class="song onlineSong"><button class="songplay onlineplay" data-oid="${esc(s.id)}">▶</button>${s.artwork?`<img class="songArt" src="${esc(s.artwork)}" alt="">`:'<div class="songArt fallback">♫</div>'}<div><b>${esc(s.title)}</b><small>${esc(s.artist)}</small></div><button class="heart onlineHeart active" data-fav-online="${esc(s.id)}">♥</button><button class="moreBtn onlineMore" data-more-online="${esc(s.id)}">&#8942;</button></div>`:card(s)).join('')||'<div class="empty">Nessun preferito.</div>'}</div>`;document.querySelectorAll('.onlineplay').forEach(b=>b.onclick=()=>{const s=state.onlineResults.find(x=>x.id===b.dataset.oid);if(s)play(s)});document.querySelectorAll('.onlineHeart').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const id=b.dataset.favOnline;state.favorites.delete(id);save();render()});document.querySelectorAll('.onlineMore').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const s=state.onlineResults.find(x=>x.id===b.dataset.moreOnline);if(s)showSongMenu(s,b)})}else if(state.tab==='memory'){c.innerHTML=`<div class="rowtitle"><div><button class="secondaryBtn" id="backMemory">← ${t('settingsTitle')}</button><h2>${state.lang==='it'?'Memoria NEXA':'NEXA Memory'}</h2></div></div><div class="settings"><div class="setting"><div style="width:100%"><b>${state.lang==='it'?'Cosa ricorda NEXA':'What NEXA remembers'}</b><label>${state.lang==='it'?'Informazioni usate per personalizzare le risposte.':'Information used to personalize replies.'}</label><div class="memoryView">${Object.keys(memory).length?Object.entries(memory).map(([k,v])=>`<div class="memoryItem"><b>${esc(k)}</b><span>${esc(typeof v==='string'?v:JSON.stringify(v))}</span></div>`).join(''):`<span class="muted">${state.lang==='it'?'Nessuna memoria salvata.':'No saved memories.'}</span>`}</div></div></div><button class="logoutBtn" id="clearMemoryPage">${state.lang==='it'?'Cancella tutta la memoria':'Clear all memory'}</button></div>`;$('#backMemory').onclick=()=>{state.tab='settings';render()};$('#clearMemoryPage').onclick=()=>{if(confirm(state.lang==='it'?'Cancellare tutta la memoria di NEXA?':'Clear all NEXA memory?')){Object.keys(memory).forEach(k=>delete memory[k]);saveMemory();render()}}}else if(state.tab==='playlists'){c.innerHTML=`<div class="rowtitle"><h2>${t('playlists')}</h2><button class="primary" id="newpl">＋</button></div><div class="playlistgrid">${state.playlists.map((p,i)=>`<button class="playlist" data-pl="${i}">${p.image?`<img class="playlistImg" src="${esc(p.image)}" alt="">`:'<span>♫</span>'}<b>${esc(p.name)}</b><small>${p.ids.length} brani</small></button>`).join('')||'<div class="empty">Crea la tua prima playlist.</div>'}</div>`;$('#newpl').onclick=async()=>{const n=prompt(state.lang==='it'?'Nome playlist':'Playlist name');if(!n)return;const picker=document.createElement('input');picker.type='file';picker.accept='image/*';picker.onchange=async()=>{state.playlists.push({name:n,ids:[],image:picker.files[0]?await imageData(picker.files[0]):''});save();render()};picker.click()};document.querySelectorAll('[data-pl]').forEach(b=>b.onclick=()=>{state.playlistOpen=Number(b.dataset.pl);state.tab='playlistDetail';render()})}else if(state.tab==='chatHistory'){const h=chatHistory();c.innerHTML=`<div class="rowtitle"><div><button class="secondaryBtn" id="backChatHistory">← ${t('settingsTitle')}</button><h2>${state.lang==='it'?'Cronologia chat':'Chat history'}</h2></div></div><div class="songs">${h.length?h.map(x=>`<div class="song historyItem"><div><b>${x.role==='user'?(state.lang==='it'?'Tu':'You'):'NEXA AI'}</b><small>${new Date(x.at||Date.now()).toLocaleString(state.lang==='it'?'it-IT':'en-US')}</small><span>${esc(x.content)}</span></div></div>`).join(''):`<div class="empty">${state.lang==='it'?'Nessuna conversazione salvata.':'No saved conversations.'}</div>`}</div>`;$('#backChatHistory').onclick=()=>{state.tab='settings';render()}}else if(state.tab==='ai'){c.innerHTML=`<div class="aihead"><span class="pill">✦ ${t('ai')}</span><h2>${t('ask')}</h2><p>${state.lang==='it'?'Chiedi informazioni su cantanti, produttori, album e musica.':'Ask about singers, producers, albums and music.'}</p></div><div id="chat" class="chat"><div class="msg bot">${state.lang==='it'?'Ciao! Sono NEXA AI. Cosa vuoi sapere sulla musica? 🎧':'Hi! I am NEXA AI. What would you like to know about music? 🎧'}</div></div><form id="aiform"><input id="aip" placeholder="${t('placeholder')}" autocomplete="off"><button type="button" id="aiMic" class="micBtn" title="Dettatura">🎙️</button><button class="primary">${t('send')}</button></form>`;$('#aiform').onsubmit=ask;setupSpeechButton($('#aiMic'),$('#aip'),()=>$('#aiform').requestSubmit())}else if(state.tab==='karaoke')c.innerHTML=`<h2>${t('karaoke')}</h2><p class="muted">${state.current?esc(state.current.title):'Seleziona un brano'}</p><div class="lyrics">${state.lrc.length?state.lrc.map(x=>`<div class="lyric">${esc(x.text)}</div>`).join(''):state.current?.lyrics?esc(state.current.lyrics).split(/\n+/).map(x=>`<div class="lyric">${esc(x)}</div>`).join(''):'Ricerca automatica del testo in corso…'}</div>`;else if(state.tab==='playlistDetail'&&state.playlistOpen!==null){const p=state.playlists[state.playlistOpen];if(!p){state.tab='playlists';return render()}const liveTracks=[...state.songs,...state.onlineResults];const storedTracks=Array.isArray(p.tracks)?p.tracks:[];const tracks=p.ids.map(id=>liveTracks.find(s=>s.id===id)||storedTracks.find(x=>x.id===id)).filter(Boolean);c.innerHTML=`<div class="playlistDetailView"><div class="rowtitle"><div><button class="secondaryBtn" id="backPlaylists">← ${t('playlists')}</button><h2>${esc(p.name)}</h2></div><div><button class="secondaryBtn" id="renamePl">✎</button> <button class="secondaryBtn" id="deletePl">🗑</button></div></div><div class="setting"><div><b>${state.lang==='it'?'Copertina playlist':'Playlist artwork'}</b></div><input id="plImage" type="file" accept="image/*"></div><div class="rowtitle"><h2>${state.lang==='it'?'Brani':'Tracks'}</h2><button class="primary" id="addToPl">＋ ${state.lang==='it'?'Aggiungi':'Add'}</button></div><div class="songs">${tracks.map(s=>`<div class="song"><button class="songplay" data-id="${s.id}">▶</button><div><b>${esc(s.title)}</b><small>${esc(s.artist)}</small></div><button class="removeFromPl" data-remove="${s.id}" aria-label="${state.lang==='it'?'Rimuovi dalla playlist':'Remove from playlist'}" title="${state.lang==='it'?'Rimuovi dalla playlist':'Remove from playlist'}">✕</button></div>`).join('')||`<div class="empty">${state.lang==='it'?'Nessun brano nella playlist.':'No tracks in this playlist.'}</div>`}</div>`;$('#backPlaylists').onclick=()=>{state.tab='playlists';state.playlistOpen=null;render()};$('#deletePl').onclick=()=>{if(confirm(state.lang==='it'?'Eliminare questa playlist?':'Delete this playlist?')){state.playlists.splice(state.playlistOpen,1);save();state.tab='playlists';state.playlistOpen=null;render()}};$('#renamePl').onclick=()=>{const n=prompt(state.lang==='it'?'Nuovo nome':'New name',p.name);if(n){p.name=n;save();render()}};$('#plImage').onchange=async e=>{if(e.target.files[0]){p.image=await imageData(e.target.files[0]);save();render()}};$('#addToPl').onclick=()=>{const available=state.songs.filter(s=>!p.ids.includes(s.id));if(!available.length)return alert(state.lang==='it'?'Importa prima un MP3.':'Import an MP3 first.');const choices=available.map((s,i)=>`${i+1}. ${s.title}`).join('\n');const pick=prompt((state.lang==='it'?'Inserisci i numeri dei brani da aggiungere (es. 1,2):':'Enter track numbers to add (e.g. 1,2):')+'\n'+choices);if(pick){pick.split(',').map(x=>parseInt(x.trim())-1).filter(i=>available[i]).forEach(i=>p.ids.push(available[i].id));save();render()}};document.querySelectorAll('.removeFromPl').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const id=b.dataset.remove;p.ids=p.ids.filter(x=>x!==id);if(Array.isArray(p.tracks))p.tracks=p.tracks.filter(x=>x.id!==id);save();render()});hookSongs();if(state.current)setPlayerText()}else if(state.tab==='expansions'){renderExpansions(c);return}else c.innerHTML=`<h2>${t('settingsTitle')}</h2><div class="settings"><div class="setting"><div><b>${state.lang==='it'?'Nome':'First name'}</b><label>${state.lang==='it'?'Nome personale':'First name'}</label></div><input id="setFirstName" value="${esc(state.firstName)}"></div><div class="setting"><div><b>${state.lang==='it'?'Cognome':'Last name'}</b><label>${state.lang==='it'?'Cognome':'Last name'}</label></div><input id="setLastName" value="${esc(state.lastName)}"></div><div class="setting"><div><b>${state.lang==='it'?'Nome visualizzato':'Display name'}</b><label>${state.lang==='it'?'Quello che NEXA userà per salutarti':'Used by NEXA to greet you'}</label></div><input id="setName" value="${esc(state.displayName||state.name)}" placeholder="Edoardo"></div><div class="setting"><div><b>${state.lang==='it'?'Data di nascita':'Date of birth'}</b><label>${state.lang==='it'?'Per la personalizzazione del compleanno':'For birthday personalization'}</label></div><input id="setBirthDate" type="date" value="${esc(state.birthDate)}"></div><div class="setting"><div><b>${t('language')}</b><label>Italiano / English</label></div><select id="setLang"><option value="it" ${state.lang==='it'?'selected':''}>🇮🇹 Italiano</option><option value="en" ${state.lang==='en'?'selected':''}>🇬🇧 English</option></select></div><div class="setting"><div><b>${state.lang==='it'?'Foto profilo':'Profile photo'}</b><label>${state.lang==='it'?'Scegli una nuova immagine e premi Salva':'Choose a new image and press Save'}</label></div><input id="setProfile" type="file" accept="image/*"></div><div class="expansionsMoved"></div><div class="spotifyMoved"></div><button class="primary" id="saveSettings">${t('save')}</button><div class="setting"><div style="width:100%"><b>${state.lang==='it'?'Memoria NEXA':'NEXA memory'}</b><label>${state.lang==='it'?'Informazioni che NEXA ricorda per personalizzare le risposte':'Information NEXA remembers to personalize replies'}</label><div id="nexaMemoryView" class="memoryView">${Object.keys(memory).length?Object.entries(memory).map(([k,v])=>`<div class="memoryItem"><b>${esc(k)}</b><span>${esc(typeof v==='string'?v:JSON.stringify(v))}</span></div>`).join(''):`<span class="muted">${state.lang==='it'?'Nessuna memoria salvata.':'No saved memories.'}</span>`}</div></div><button class="secondaryBtn" id="openMemory">${state.lang==='it'?'Apri memoria':'Open memory'}</button> <button class="secondaryBtn" id="clearMemory">${state.lang==='it'?'Cancella memoria':'Clear memory'}</button></div><div class="setting"><div><b>${state.lang==='it'?'Cronologia chat':'Chat history'}</b><label>${state.lang==='it'?'Le conversazioni vengono salvate per la cronologia.':'Conversations are saved to history.'}</label></div><button class="secondaryBtn" id="openChatHistory">${state.lang==='it'?'Apri cronologia':'Open history'}</button><button class="secondaryBtn" id="clearHistory">${state.lang==='it'?'Cancella cronologia':'Clear history'}</button></div></div>`;hookSongs();if($('#openMemory'))$('#openMemory').onclick=()=>{state.tab='memory';render()};if($('#clearMemory'))$('#clearMemory').onclick=()=>{if(confirm(state.lang==='it'?'Cancellare tutta la memoria di NEXA?':'Clear all NEXA memory?')){Object.keys(memory).forEach(k=>delete memory[k]);saveMemory();render()}};if($('#openChatHistory'))$('#openChatHistory').onclick=()=>{state.tab='chatHistory';render()};if($('#clearHistory'))$('#clearHistory').onclick=()=>{localStorage.removeItem('nexaChatHistory');alert(state.lang==='it'?'Cronologia chat cancellata.':'Chat history cleared.')};if($('#spotifySetup'))$('#spotifySetup').onclick=async()=>{state.spotify.clientId=$('#spotifyClientId')?.value.trim()||state.spotify.clientId;localStorage.nexaSettings=JSON.stringify({...JSON.parse(localStorage.nexaSettings||'{}'),spotifyClientId:state.spotify.clientId});if(state.spotify.accessToken){await spotifyInitPlayer();alert(state.lang==='it'?'Spotify è già collegato. 🎧':'Spotify is already connected. 🎧')}else await spotifyConnect()};if($('#spotifyDisconnect'))$('#spotifyDisconnect').onclick=()=>spotifyDisconnect();if($('#lyraDirect'))$('#lyraDirect').onclick=null;if(state.current)setPlayerText()}
function hookSongs(){if(state.tab==='settings'&&!$('#logoutBtn')){const saveBtn=$('#saveSettings');if(saveBtn){const b=document.createElement('button');b.id='logoutBtn';b.className='logoutBtn';b.textContent=state.lang==='it'?'Esci':'Log out';b.onclick=async()=>{if(confirm(state.lang==='it'?'Vuoi uscire da NEXA Music?':'Log out of NEXA Music?')){try{await window.hatchable.auth.signOut()}catch(e){console.warn('Logout failed',e)}finally{state.authEmail='';state.current=null;state.songs=[];state.onlineResults=[];location.replace('/login')}}};saveBtn.insertAdjacentElement('afterend',b)}}document.querySelectorAll('.songplay').forEach(b=>b.onclick=()=>play(state.songs.find(s=>s.dataset?.id===b.dataset.id)||state.songs.find(s=>s.id===b.dataset.id)));document.querySelectorAll('[data-more]').forEach(b=>b.onclick=e=>{e.stopPropagation();const s=state.songs.find(x=>x.id===b.dataset.more);if(s)showSongMenu(s,b)});document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const id=b.dataset.fav;if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);save();b.textContent=state.favorites.has(id)?'♥':'♡';b.classList.toggle('active',state.favorites.has(id))});if($('#setProfile'))$('#setProfile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){alert(state.lang==='it'?'Seleziona un\'immagine valida.':'Choose a valid image.');e.target.value='';return}state.profileImage=await imageData(f);const p=$('#profile');if(p)p.innerHTML=`<img src="${esc(state.profileImage)}" alt="Profilo">`};if($('#saveSettings'))$('#saveSettings').onclick=async()=>{state.firstName=$('#setFirstName')?.value.trim()||'';state.lastName=$('#setLastName')?.value.trim()||'';state.displayName=$('#setName').value.trim();state.name=state.displayName;state.birthDate=$('#setBirthDate')?.value||'';state.lang=$('#setLang').value;const f=$('#setProfile')?.files?.[0];const profileImageData=f?await imageData(f):'';try{const r=await fetch('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({first_name:state.firstName,last_name:state.lastName,display_name:state.displayName,birth_date:state.birthDate,language:state.lang,profile_image_data:profileImageData})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Profile save failed');if(d.profile_image_url){state.profileImage=d.profile_image_url+'?v='+Date.now();}else if(f){throw new Error(state.lang==='it'?'Il server non ha restituito la foto salvata.':'The server did not return the saved photo.')}save();const notice=document.createElement('div');notice.className='saveNotice';notice.textContent=state.lang==='it'?'Informazioni salvate':'Information saved';notice.style.cssText='position:fixed;left:50%;bottom:110px;transform:translateX(-50%);z-index:10000;padding:11px 18px;border-radius:12px;background:rgba(18,28,38,.96);color:#fff;font-weight:700;box-shadow:0 8px 30px rgba(0,0,0,.3);pointer-events:none';document.body.appendChild(notice);setTimeout(()=>notice.remove(),2200);}catch(e){console.warn('Profile save failed',e);alert(state.lang==='it'?'Impossibile salvare il profilo.':'Unable to save profile.');return}shell();if(state.birthDate&&new Date().toISOString().slice(5,10)===state.birthDate.slice(5,10))showBirthday()}}
async function ask(e){e.preventDefault();const input=$('#aip'),q=input.value.trim();if(!q)return;const chat=$('#chat');input.blur();
const pref=q.match(/(?:mi piace|mi piacciono|amo|adoro|preferisco|my favorite|i like|i love|i prefer)\s+(.+)/i);if(pref){memory.preferences=memory.preferences?memory.preferences+'; '+pref[1].slice(0,180):pref[1].slice(0,180);saveMemory()}const hist=chatHistory();hist.push({role:'user',content:q,at:new Date().toISOString()});saveChatHistory(hist);chat.insertAdjacentHTML('beforeend',`<div class="msg user">${esc(q)}</div><div class="msg bot typing">${state.lang==='it'?'NEXA sta pensando…':'NEXA is thinking…'}</div>`);input.value='';input.disabled=true;const history=[...chat.querySelectorAll('.msg')].slice(-6).map(m=>({role:m.classList.contains('user')?'user':'assistant',content:m.textContent}));try{const r=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:history,language:state.lang,memory:`Nome: ${state.name||'non specificato'}. Preferenze note: ${memory.preferences||'nessuna'}. ${memory.notes||''}.`,currentTrack:state.current?{title:state.current.title,artist:state.current.artist}:null})});const d=await r.json();const typing=chat.querySelector('.typing:last-child');if(typing){typing.classList.remove('typing');typing.textContent=r.ok?d.text:(d.error||'NEXA AI non disponibile.');const h=chatHistory();h.push({role:'assistant',content:typing.textContent,at:new Date().toISOString()});saveChatHistory(h)}}catch(x){const typing=chat.querySelector('.typing:last-child');if(typing){typing.classList.remove('typing');typing.textContent=state.lang==='it'?'Errore di connessione a NEXA AI.':'NEXA AI connection error.'}}finally{input.disabled=false;input.blur();requestAnimationFrame(()=>{chat.scrollTo({top:chat.scrollHeight,behavior:'smooth'});window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})})}}
shell();addSearchBox();restoreOfflineTracks();initAuth();initSpotify();setInterval(updateGreeting,30000);setInterval(updateGlobalTimer,1000);setInterval(syncYoutubeProgress,500);